
const $=s=>document.getElementById(s);let state;try{state=JSON.parse(localStorage.getItem('compass-v1'))||{}}catch{state={}}state={cv:'',interests:'',results:[],saved:[],apps:[],major:'',level:'',applicant:'',plan:null,connections:[],school:'',graduation:'',courses:'',skills:'',hours:'',payPreference:'',liveItems:[],liveSources:[],savedOpportunities:[],...state};let view='discover',selected;let demoMode=false,demoBackup=null,demoStep=0;
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){if(!demoMode){try{localStorage.setItem('compass-v1',JSON.stringify(state))}catch{toast('Device storage is full. Keep this tab open; recent changes may not survive a reload.')}}render()}
['major','level','applicant'].forEach(k=>{$(k).value=state[k]||'';$(k).onchange=()=>{state[k]=$(k).value;persist()}});$('cv').value=state.cv;$('interests').value=state.interests;function words(){ $('wordcount').textContent=($('cv').value.trim().match(/\S+/g)||[]).length+' words · stored only on this device'}words();$('cv').oninput=()=>{state.cv=$('cv').value;words();persist()};$('interests').oninput=()=>{state.interests=$('interests').value;persist()};$('clear').onclick=()=>{state.cv='';$('cv').value='';words();persist()};$('file').onchange=async e=>{let f=e.target.files[0];if(!f)return;if(f.size>1000000){toast('Please use a text file under 1 MB.');return}state.cv=await f.text();$('cv').value=state.cv;$('filename').textContent=f.name;words();persist()};
function toast(t){let el=document.createElement('div');el.className='toast';el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),3500)}
function card(r){let saved=state.saved.some(x=>x.url===r.url);return '<article class="match"><div class="row"><div><span class="eyebrow">FACULTY RESEARCH ALIGNMENT</span><h2 style="margin-top:9px">'+esc(r.name)+'</h2></div><span class="score">'+r.shared.length+' shared terms</span></div><div class="tags">'+r.shared.map(t=>'<span class="tag">'+esc(t)+'</span>').join('')+'</div><p>'+esc(r.excerpt)+'</p><p class="tiny">Opening status: unverified · Retrieved '+esc(r.date)+'</p><div class="row"><a href="'+esc(r.url)+'" target="_blank" rel="noopener">Read faculty page ↗</a><div><button class="secondary" data-save="'+esc(r.url)+'">'+(saved?'★ Saved':'☆ Save')+'</button> <button class="primary" data-draft="'+esc(r.url)+'">Draft outreach ↗</button></div></div>'+facultyReview(r)+calendarButton('coffee',r.name,r.url)+'</article>'}
function render(){renderPlan();renderNamedPeople(); $('total').textContent=state.results.length||'—';$('savedTotal').textContent=state.saved.length;$('savedCount').textContent=state.saved.length||'';$('appTotal').textContent=state.apps.length;$('results').innerHTML=state.results.length?'<h2 style="margin-top:32px">Your research connections</h2><p class="tiny">Keyword overlap, not a probability of acceptance. Check each faculty page before contacting.</p>'+state.results.map(card).join(''):'';$('shortlist').innerHTML=state.saved.length?state.saved.map(card).join(''):'<div class="empty"><h2>A little curiosity goes a long way.</h2><p>Save a faculty match to build your shortlist.</p></div>';$('applications').innerHTML=state.apps.length?state.apps.map((a,i)=>'<article class="match"><div class="row"><h2>'+esc(a.name)+'</h2><button class="secondary" data-remove="'+i+'">Remove</button></div><p class="tiny">Added '+esc(a.date)+'</p><label>Status</label><select data-status="'+i+'">'+['Drafting','Contacted','Follow-up','Interview','Closed'].map(s=>'<option '+(s===a.status?'selected':'')+'>'+s+'</option>').join('')+'</select><label>Outreach draft / notes</label><textarea data-notes="'+i+'">'+esc(a.draft)+'</textarea><a href="'+esc(a.url)+'" target="_blank" rel="noopener">Faculty source ↗</a>'+calendarButton('deadline',a.name,a.url)+calendarButton('coffee',a.name,a.url)+'</article>').join(''):'<div class="empty"><h2>Your next conversation starts here.</h2><p>Create an outreach draft from a match, then add it to applications.</p></div>';renderLive();renderApplications();let allSaved=state.saved.length+(state.savedOpportunities||[]).length;$('savedTotal').textContent=allSaved;$('savedCount').textContent=allSaved||'';if(state.savedOpportunities?.length)$('shortlist').innerHTML=(state.saved.length?$('shortlist').innerHTML:'')+'<h2>Saved opportunities</h2>'+state.savedOpportunities.map(liveItemCard).join('');}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;['discover','shortlist','applications','opportunities','network','live'].forEach(v=>$(v).classList.toggle('hidden',v!==view));document.querySelectorAll('nav button').forEach(n=>n.classList.toggle('active',n===b));$('breadcrumb').textContent=b.textContent.trim();$('pageTitle').textContent={live:'Find your next opening.',opportunities:'More ways to move forward.',network:'Build your circle.',discover:'Find where you belong.',shortlist:'Follow your curiosity.',applications:'Turn connections into possibilities.'}[view];$('pageSubtitle').textContent={live:'Current public listings, profile evidence, and clear next steps.',opportunities:'Industry, community, and campus pathways shaped around your profile.',network:'Start a thoughtful conversation with someone who shares your interests.',discover:'Connect your experience with the people moving research forward.',shortlist:'Your saved faculty and research connections, in one place.',applications:'Keep every draft, conversation, and next step in view.'}[view]});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.save){let r=[...state.results,...state.saved].find(x=>x.url===b.dataset.save);state.saved=state.saved.some(x=>x.url===r.url)?state.saved.filter(x=>x.url!==r.url):[...state.saved,r];persist()}if(b.dataset.draft){selected=[...state.results,...state.saved].find(x=>x.url===b.dataset.draft);openDraft(selected,b)}if(b.dataset.remove!==undefined){state.apps.splice(+b.dataset.remove,1);persist()}});
document.addEventListener('change',e=>{if(e.target.dataset.status!==undefined){state.apps[+e.target.dataset.status].status=e.target.value;persist()}if(e.target.dataset.notes!==undefined){state.apps[+e.target.dataset.notes].draft=e.target.value;if(!demoMode)localStorage.setItem('compass-v1',JSON.stringify(state))}});$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('draft').value);toast('Draft copied')}catch{toast('Select the draft text to copy it.')}};$('track').onclick=()=>{let old=state.apps.find(a=>a.url===selected.url);if(old)old.draft=$('draft').value;else state.apps.push({...selected,draft:$('draft').value,status:'Drafting',date:new Date().toLocaleDateString()});persist();$('draftDialog').close();toast('Saved to applications')};
$('run').onclick=async()=>{if(demoMode){loadDemoMatches();return}if(!state.major.trim()){ $('error').textContent='Add your major or field so we can find relevant Columbia departments.';$('major').focus();return}if(state.cv.trim().length<80){$('error').textContent='Add at least 80 characters from your CV so there is enough context to match.';return}$('error').textContent='';$('run').disabled=true;$('progress').classList.remove('hidden');try{let r=await fetch('/api/discover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cv:profileText(state),major:state.major,interests:[state.interests,typeof activeResearch==='function'?activeResearch()?.question:''].filter(Boolean).join(' ')})});let data=await r.json();if(!r.ok)throw Error(data.error);state.results=data.results;$('discoverySources').innerHTML=(data.sources||[]).map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.name)+' ↗</a>').join(' · ');persist();$('error').textContent=data.results.length?'Read '+data.scanned+' pages. '+data.failed+' pages could not be read.':'No shared research terms found across '+data.scanned+' pages. Try adding more specific research interests or a related field.';if(data.results.length)$('results').scrollIntoView({behavior:'smooth'})}catch(e){$('error').textContent=e.message}finally{$('run').disabled=false;$('progress').classList.add('hidden')}};

async function openDraft(person,button){if(demoMode){openDemoDraft(person);return}let label=button.textContent;button.disabled=true;button.textContent='Reading research…';try{let response=await fetch('/api/draft',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:person.url,cv:profileText(state),major:state.major,level:state.level,applicant:state.applicant})});let d=await response.json();if(!response.ok)throw Error(d.error);let existing=state.apps.find(a=>a.url===person.url);$('draft').value=existing?.draft||d.draft;$('draftEvidence').classList.remove('hidden');$('draftEvidence').innerHTML='<b>Source-grounded draft</b><br>'+d.evidence.map(e=>'<p style="margin:8px 0">“'+esc(e.text)+'”<br><a target="_blank" rel="noopener" href="'+esc(e.url)+'">Read source ↗</a></p>').join('')+'<span class="tiny">CV connection: '+esc(d.cvEvidence||'No clear CV overlap — add a relevant project before sending.')+'</span>';state.connections=[...new Map([...state.connections,...d.connections].map(c=>[c.url,c])).values()];persist();$('draftDialog').showModal()}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent=label}}
$('plan').onclick=()=>{if(!state.major.trim()||!state.level){toast('Add your major and class level in Discover matches first.');return}state.plan={major:state.major,level:state.level};persist();$('planResults').scrollIntoView({behavior:'smooth'})};
const careerURL='https://www.alumni.columbia.edu/content/school-based-job-boards-and-career-coaching',clubsURL='https://entrepreneurship.columbia.edu/resource/entrepreneurship-student-clubs/';
const pathways=[
{test:/computer|software|data|math|statistic|artificial|informatics/i,roles:['Software engineering','Data analytics','Product analytics'],skill:'Build one reproducible coding or data project and show the problem, method, and result.',people:'software engineers, data analysts, and product managers',query:'software engineer data analyst'},
{test:/econom|business|financ|account/i,roles:['Financial analysis','Economic consulting','Business operations'],skill:'Prepare an analysis using a real dataset, a financial model, or a concise market memo.',people:'financial analysts, economic consultants, and operations associates',query:'financial analyst economic consulting'},
{test:/bio|chem|neuro|premed|pre-med|health/i,roles:['Biotech operations','Clinical operations','Healthcare consulting'],skill:'Highlight careful documentation, data analysis, and relevant lab or health coursework; clinical roles may require extra training.',people:'biotech associates, clinical operations coordinators, and healthcare analysts',query:'biotech clinical operations'},
{test:/mechan|electrical|civil|engineering|material/i,roles:['Engineering design','Product testing','Technical operations'],skill:'Build a design portfolio with technical drawings, simulations, or a prototype and validation results.',people:'design engineers, test engineers, and technical program managers',query:'engineering design product testing'},
{test:/politic|policy|international|sociolog|anthropolog/i,roles:['Policy analysis','Public affairs','Nonprofit programs'],skill:'Prepare a short policy brief or program evaluation grounded in evidence.',people:'policy analysts, public affairs associates, and nonprofit program coordinators',query:'policy public affairs nonprofit'},
{test:/psych|cognitive|education/i,roles:['User experience','Learning and development','People operations'],skill:'Show an ethical interview, survey, or learning-design project with a clear analysis.',people:'UX researchers, learning designers, and people operations associates',query:'user experience learning development'},
{test:/english|history|literature|art|film|music|philosoph|humanit|communication/i,roles:['Editorial and publishing','Arts administration','Communications'],skill:'Create a small writing, curation, or communications portfolio adapted to your target audience.',people:'editors, museum program staff, and communications associates',query:'editorial arts communications'},
{test:/environment|climate|sustain|earth/i,roles:['Sustainability analysis','Climate programs','Environmental consulting'],skill:'Show a sustainability case study or geospatial/data project and explain its practical implications.',people:'sustainability analysts, climate program coordinators, and environmental consultants',query:'sustainability environmental consulting'}];
function getPath(m){return pathways.find(p=>p.test.test(m))||{roles:[m+' related operations',m+' project coordination','Cross-functional analyst'],skill:'Translate a course project into a portfolio sample and map its skills to the requirements of each role.',people:'early-career alumni in '+m+', program coordinators, and hiring-event speakers',query:m}}
function renderPlan(){if(!$('planResults'))return;let m=state.plan?.major||state.major,l=state.plan?.level||state.level;let path=getPath(m||'your field'),early=['First year','Sophomore'].includes(l),senior=l==='Senior',grad=['Master’s','Doctoral'].includes(l);let stage=early?'Explore insight events, job shadowing, and introductory internships. Check whether each program accepts your graduation year.':senior?'Prioritize new-graduate roles and graduate schemes; keep internships only where final-year students are eligible.':grad?'Prioritize graduate-level internships and specialist roles; match degree requirements and graduation dates.':'Prioritize summer internships and project-based roles; check graduation-year requirements.';
function item(title,body,url,action){return '<article class="match"><div class="eyebrow">SUGGESTED PATHWAY · NOT A VERIFIED OPENING</div><h2 style="margin-top:10px">'+esc(title)+'</h2><p>'+esc(body)+'</p><a target="_blank" rel="noopener" href="'+esc(url)+'">'+esc(action||'Explore official resource')+' ↗</a>'+calendarButton('opportunity',title,url)+'</article>'}
if(state.plan){$('planResults').innerHTML='<p><b>'+esc(m)+' · '+esc(l)+'</b></p><div class="notice">These are role targets and official discovery resources, not live job listings. Verify deadlines, prerequisites, and school access on the linked site. Rebuild this plan after changing your profile.</div>'+path.roles.map(role=>item(role+(senior?' — entry level':' — internship / experience'),stage+' '+path.skill+' Your '+m+' studies provide a starting point; compare your CV against the actual job description.',careerURL,'Find your school’s job board')).join('')+item('Student entrepreneurship & project teams','Explore student clubs and teams where you can contribute '+m+' skills. '+(early?'Start with a contributor role and one defined project.':'Look for a project, committee, or leadership role supported by your experience.'),clubsURL)+item('Community Impact — service experience','Explore community programs and contribute skills from '+m+'. Confirm current volunteer intake, training, and time commitments.', 'https://www.communityimpact.columbia.edu/content/program-volunteer')+item('Campus health advocacy and student employment','Explore Columbia Health’s volunteer and employment information. Evaluate each role’s prerequisites and whether it fits your schedule.','https://www.health.columbia.edu/content/student-employment-and-volunteer-opportunities');}
let contacts=[{title:'Early-career alumni in '+(m||'your major'),body:'Look for '+path.people+'. Ask about one transition from coursework to work, rather than asking immediately for a referral.',url:careerURL},{title:'Career adviser serving your school',body:'Bring your CV and ask which '+(l||'class-level')+' recruiting routes match '+(m||'your major')+'. School access and advising eligibility vary.',url:careerURL},{title:'Student project or entrepreneurship leaders',body:'Find a current organizer, explain one concrete skill you can contribute, and ask about an upcoming project.',url:clubsURL}];$('networkResults').innerHTML=(!m||!l?'<div class="notice">Add your major and class level to tailor these suggestions.</div>':'')+contacts.map(c=>'<article class="match"><span class="eyebrow">SUGGESTED CONNECTION TYPE</span><h2 style="margin-top:10px">'+esc(c.title)+'</h2><p>'+esc(c.body)+'</p><a href="'+esc(c.url)+'" target="_blank" rel="noopener">Find people through official resources ↗</a><p class="tiny">Suggested opener: Hi [name], I’m a '+esc(l||'[class level]')+' student studying '+esc(m||'[major]')+'. I’m exploring '+esc(path.roles[0])+'. Would you be open to sharing one piece of advice about getting started?</p>'+calendarButton('coffee',c.title,c.url)+'</article>').join('')+(state.connections.length?'<h2>People linked from faculty research pages</h2>'+state.connections.map(c=>'<article class="match"><span class="eyebrow">NAME EXTRACTED FROM SOURCE · ROLE UNVERIFIED</span><h2 style="margin-top:10px">'+esc(c.name)+'</h2><p>'+esc(c.context)+'</p><a href="'+esc(c.url)+'" target="_blank" rel="noopener">Read linked profile ↗</a> · <a href="'+esc(c.source)+'" target="_blank" rel="noopener">Faculty source ↗</a>'+calendarButton('coffee',c.name,c.url)+'</article>').join(''):'<div class="source">Create a professor-specific draft to discover people linked from that professor’s research pages. Names are never invented.</div>')}

function calendarButton(kind,title,url){return '<button type="button" style="margin:15px 8px 0 0" class="secondary" data-calendar="'+kind+'" data-event-title="'+esc(title)+'" data-event-source="'+esc(url)+'">'+(kind==='coffee'?'☕ Plan coffee chat':kind==='deadline'?'▦ Add deadline':'▦ Add to Google Calendar')+'</button>'}
function openCalendar(kind='opportunity',title='',source=''){ $('calendarError').textContent='';$('eventKind').value=kind;$('eventTitle').value=(kind==='coffee'?'Coffee chat — ':kind==='deadline'?'Application deadline — ':kind==='followup'?'Follow up — ':'Explore — ')+title;if(!title)$('eventTitle').value='';$('eventDate').value='';$('eventEndDate').value='';$('eventStart').value='10:00';$('eventEnd').value='10:30';$('eventAllDay').checked=kind==='deadline'||kind==='followup';$('eventLocation').value='';$('eventNotes').value=source?'Source: '+source:'';try{$('eventZone').value=Intl.DateTimeFormat().resolvedOptions().timeZone||'America/New_York'}catch{$('eventZone').value='America/New_York'}toggleEventTime();$('calendarDialog').showModal()}
function toggleEventTime(){let all=$('eventAllDay').checked;$('eventTimeFields').classList.toggle('hidden',all);$('eventStart').required=!all;$('eventEnd').required=!all;$('eventZone').required=!all}
$('eventAllDay').onchange=toggleEventTime;$('eventKind').onchange=()=>{if($('eventKind').value==='deadline'){$('eventAllDay').checked=true;toggleEventTime()}};$('eventDate').onchange=()=>{if(!$('eventEndDate').value||$('eventEndDate').value<$('eventDate').value)$('eventEndDate').value=$('eventDate').value};$('newCalendarEvent').onclick=()=>openCalendar();$('closeCalendar').onclick=()=>$('calendarDialog').close();document.addEventListener('click',e=>{let b=e.target.closest('button[data-calendar]');if(b)openCalendar(b.dataset.calendar,b.dataset.eventTitle,b.dataset.eventSource)});
function zonedInstant(date,time,zone){let wall=date+'T'+time+':00';let base=Date.parse(wall+'Z');if(!Number.isFinite(base))throw Error('Enter valid dates and times.');let formatter;try{formatter=new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'})}catch{throw Error('Enter a valid IANA time zone.')}function stamp(ms){let p=Object.fromEntries(formatter.formatToParts(new Date(ms)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return p.year+'-'+p.month+'-'+p.day+'T'+p.hour+':'+p.minute+':'+p.second}let candidates=new Set();for(let delta of [-86400000,0,86400000]){let probe=base+delta;let offset=Date.parse(stamp(probe)+'Z')-probe;let guess=base-offset;if(stamp(guess)===wall)candidates.add(guess)}if(!candidates.size)throw Error('That time does not exist due to a daylight-saving change. Choose another time.');if(candidates.size>1)throw Error('That time occurs twice due to a daylight-saving change. Choose another time, or enter the intended UTC time with time zone UTC.');return new Date([...candidates][0])}
function makeCalendarURL(event){if(!event.title.trim())throw Error('Add an event title.');if(!/^\d{4}-\d{2}-\d{2}$/.test(event.startDate)||!/^\d{4}-\d{2}-\d{2}$/.test(event.endDate))throw Error('Choose a start and end date.');if(event.endDate<event.startDate)throw Error('The end date must be on or after the start date.');let dates;if(event.allDay){let end=new Date(event.endDate+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+1);dates=event.startDate.replaceAll('-','')+'/'+end.toISOString().slice(0,10).replaceAll('-','')}else{if(!/^\d{2}:\d{2}$/.test(event.startTime)||!/^\d{2}:\d{2}$/.test(event.endTime))throw Error('Choose start and end times.');let start=zonedInstant(event.startDate,event.startTime,event.zone),end=zonedInstant(event.endDate,event.endTime,event.zone);if(end<=start)throw Error('End time must be after start time. For an overnight event, change the end date.');let fmt=d=>d.toISOString().replace(/[-:]/g,'').replace('.000','');dates=fmt(start)+'/'+fmt(end)}let url=new URL('https://calendar.google.com/calendar/r/eventedit');url.search=new URLSearchParams({action:'TEMPLATE',text:event.title,dates,details:event.notes||'',location:event.location||'',...(!event.allDay?{stz:event.zone,etz:event.zone,ctz:event.zone}:{})}).toString();return url.href}
$('calendarForm').onsubmit=e=>{e.preventDefault();try{let url=makeCalendarURL({title:$('eventTitle').value,startDate:$('eventDate').value,endDate:$('eventEndDate').value,startTime:$('eventStart').value,endTime:$('eventEnd').value,zone:$('eventZone').value.trim(),allDay:$('eventAllDay').checked,notes:$('eventNotes').value,location:$('eventLocation').value});window.open(url,'_blank','noopener,noreferrer');$('calendarError').textContent='';toast('Google Calendar draft opened. Click Save there to add the event.')}catch(err){$('calendarError').textContent=err.message}};

const PEOPLE_CATALOG=[{"id": "kevin", "name": "Kevin C. Wang", "role": "Data-science entrepreneurship mentor listed by QMSS", "url": "https://qmss.columbia.edu/directory/kevin-c-wang", "summary": "Data and cloud investing; mentoring students exploring data-driven ventures.", "tags": ["computer", "data", "math", "statistic", "econom", "business", "financ", "software", "entrepreneur"], "question": "How do you evaluate a data-driven startup, and what should a student build to learn that process?", "access": "QMSS mentor route; confirm whether opportunities extend beyond QMSS.", "checked": "2026-11-09"}, {"id": "laura", "name": "Laura Uguccioni", "role": "QMSS alumna with data-science consulting experience", "url": "https://qmss.columbia.edu/directory/laura-uguccioni", "summary": "NLP and probabilistic modeling, with a background in consulting and educational AI tools.", "tags": ["computer", "data", "statistic", "psych", "cognitive", "education", "software", "math"], "question": "Which portfolio project best demonstrates readiness for applied NLP or analytics consulting?", "access": "Listed through QMSS; availability is not confirmed.", "checked": "2026-11-09"}, {"id": "ricardo", "name": "Ricardo Bustamante", "role": "Community Impact senior program coordinator", "url": "https://www.communityimpact.columbia.edu/directory/ricardo-bustamante", "summary": "Food programs and advising student-led health, housing, and community-service groups.", "tags": ["health", "bio", "neuro", "policy", "sociolog", "social", "community", "volunteer", "premed"], "question": "How could I contribute consistently to a student-led food, health, or housing program?", "access": "Ask about student volunteer routes and training.", "checked": "2026-11-09"}, {"id": "georgia", "name": "Georgia Trim", "role": "Community Impact adult-education leader", "url": "https://www.communityimpact.columbia.edu/directory/georgia-trim", "summary": "Adult learning, literacy, and community education programming.", "tags": ["education", "psych", "english", "literature", "humanit", "language", "history", "volunteer"], "question": "What preparation is most useful for a student supporting adult learning or literacy?", "access": "Ask the program about current volunteer intake.", "checked": "2026-11-09"}, {"id": "caitlin", "name": "Caitlin Hughes", "role": "Community Impact youth-program leader", "url": "https://www.communityimpact.columbia.edu/directory/caitlin-hughes", "summary": "Youth education, college access, and collaboration between students and community partners.", "tags": ["education", "policy", "politic", "international", "sociolog", "psych", "community", "volunteer"], "question": "Which youth or college-access projects would benefit from a student with my skills?", "access": "Ask about the program\u2019s semester commitment and training.", "checked": "2026-11-09"}, {"id": "houtan", "name": "Houtan Fanisalek", "role": "CTO in Residence listed by Columbia Startup Lab", "url": "https://entrepreneurship.columbia.edu/startup-lab/", "summary": "A technical leadership perspective on building early-stage ventures.", "tags": ["computer", "software", "engineering", "electrical", "mechan", "data", "entrepreneur"], "question": "Which technical tradeoffs should a student founder consider before building a first prototype?", "access": "CSL SoHo serves alumni ventures; ask about public events or introductions, not guaranteed mentor access.", "checked": "2026-11-09"}, {"id": "jonte", "name": "Jonte\u0301 Harrell", "role": "CFO in Residence listed by Columbia Startup Lab", "url": "https://entrepreneurship.columbia.edu/startup-lab/", "summary": "A finance leadership perspective for early-stage ventures.", "tags": ["econom", "business", "financ", "account", "entrepreneur"], "question": "What financial assumptions should a first-time founder validate before raising money?", "access": "CSL SoHo serves alumni ventures; confirm access through the program.", "checked": "2026-11-09"}, {"id": "sarah", "name": "Sarah Holloway", "role": "Social entrepreneurship mentor listed by Columbia Startup Lab", "url": "https://entrepreneurship.columbia.edu/startup-lab/", "summary": "Social entrepreneurship at the intersection of ventures and public benefit.", "tags": ["policy", "politic", "international", "sociolog", "health", "environment", "climate", "sustain", "social", "entrepreneur"], "question": "How can a student test whether a social venture addresses a real community need?", "access": "Ask about accessible programs or public events; mentor access is not guaranteed.", "checked": "2026-11-09"}, {"id": "elizabeth", "name": "Elizabeth Leahy", "role": "Pitch coach in Residence listed by Columbia Startup Lab", "url": "https://entrepreneurship.columbia.edu/startup-lab/", "summary": "Pitch coaching for communicating an early-stage venture.", "tags": ["business", "communication", "english", "art", "film", "humanit", "design", "entrepreneur"], "question": "What makes a student project pitch clear and credible to a non-specialist audience?", "access": "Confirm program eligibility and public contact routes.", "checked": "2026-11-09"}, {"id": "shazna", "name": "Shazna Nessa", "role": "Journalism, technology, and design professional profiled by Brown Institute", "url": "https://brown.columbia.edu/portfolio/shazna-nessa/", "summary": "Experience in visual journalism and digital storytelling across media organizations.", "tags": ["english", "art", "design", "film", "communication", "history", "humanit", "journal", "data"], "question": "How can a student combine a storytelling portfolio with technical or visual-design skills?", "access": "Read the dated profile and confirm current roles before reaching out.", "checked": "2026-11-09"}];
function rankedPeople(){let major=(state.major||'').toLowerCase(),profile=(state.interests+' '+state.cv).toLowerCase();return (state.peopleSnapshot||PEOPLE_CATALOG).map(p=>({...p,majorTags:p.tags.filter(t=>major.includes(t)),sharedTags:p.tags.filter(t=>profile.includes(t)),score:p.tags.reduce((n,t)=>n+(major.includes(t)?6:profile.includes(t)?1:0),0)})).sort((a,b)=>b.score-a.score)}
function personReason(p){let field=state.major||'your field';return p.majorTags.length?'Their public background connects to '+field+' through '+p.majorTags.slice(0,2).join(' and ')+'.':p.sharedTags.length?'Your CV or interests overlap in '+p.sharedTags.slice(0,3).join(', ')+'.':'A broader connection to explore alongside '+field+'; no direct field overlap was found.'}
function personOpener(p){let stage=['First year','Sophomore'].includes(state.level)?'I’m exploring career directions and a first practical project.':state.level==='Senior'?'I’m preparing for the transition from college to work.':['Master’s','Doctoral'].includes(state.level)?'I’m exploring how to apply my specialist training outside academia.':'I’m exploring internships and ways to apply my coursework.';return 'Hi '+p.name.split(' ')[0]+', I’m '+(state.applicant||'[name]')+', a '+(state.level||'[class level]').toLowerCase()+' student studying '+(state.major||'[major]')+'. '+stage+' I noticed this focus in your public profile: “'+p.summary+'” '+p.question+' If appropriate, would you be open to a brief conversation?'}
function personCard(p){return '<article class="match"><div class="row"><div class="row"><span class="person-initial">'+esc(p.name.split(' ').map(n=>n[0]).slice(0,2).join(''))+'</span><h2>'+esc(p.name)+'</h2></div></div><div class="person-role">'+esc(p.role)+'</div><p>'+esc(p.summary)+'</p><p><b>Why connect:</b> '+esc(personReason(p))+'</p><p class="tiny">'+esc(p.access)+'</p><div class="person-opener">'+esc(personOpener(p))+'</div><p class="tiny">Source '+(p.liveChecked?'reread':'reviewed')+': '+esc(p.liveChecked||p.checked)+' · Availability unconfirmed</p><div class="person-actions"><a href="'+esc(p.url)+'" target="_blank" rel="noopener">Public profile / listing ↗</a><button class="secondary" data-copy-person="'+esc(p.id)+'">Copy opener</button><button class="secondary" data-log-person="'+esc(p.id)+'">Log outreach</button></div>'+calendarButton('coffee',p.name,p.url)+'</article>'}
function renderNamedPeople(){let list=rankedPeople();let summary='<p class="tiny">Named suggestions from public Columbia profiles and mentor listings, ranked by your major, CV, and interests. Class level shapes the conversation starter. Program access and coffee-chat availability are not guaranteed.</p>';let controls='<button class="secondary" data-refresh-people>↻ Recheck sources</button>';let status=state.peopleRefreshStatus?'<p class="tiny">'+esc(state.peopleRefreshStatus)+'</p>':'';$('beyondPeople').innerHTML='<div class="people-toolbar"><h2>People to meet beyond the lab</h2>'+controls+'</div>'+summary+status+'<div class="people-grid">'+list.slice(0,4).map(personCard).join('')+'</div>';$('namedPeople').innerHTML='<div class="people-toolbar"><h2>Your suggested connections</h2>'+controls+'</div>'+summary+(!state.major?'<div class="notice">Add your major in Discover matches to rank these names for your field.</div>':'')+status+'<div class="people-grid">'+list.slice(0,8).map(personCard).join('')+'</div>'}
let peopleRefreshing=false;async function refreshPeople(){if(peopleRefreshing)return;if(demoMode){toast('Demo uses source snapshots reviewed on November 9, 2026.');return}peopleRefreshing=true;document.querySelectorAll('[data-refresh-people]').forEach(b=>{b.disabled=true;b.textContent='Checking…'});try{let r=await fetch('/api/people');let d=await r.json();if(!r.ok)throw Error(d.error);state.peopleSnapshot=d.people;state.peopleRefreshStatus=d.people.length+' names found on reread source pages. '+d.failed+' sources unavailable; names from those sources are hidden. Roles remain source snapshots — confirm on the profile.';persist()}catch(e){toast('Could not recheck sources. Showing the dated source snapshots.')}finally{peopleRefreshing=false;renderNamedPeople()}}
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-refresh-people'))refreshPeople();if(b.dataset.copyPerson){let p=rankedPeople().find(p=>p.id===b.dataset.copyPerson);try{await navigator.clipboard.writeText(personOpener(p));toast('Personalized opener copied')}catch{toast('Select the visible opener text to copy it.')}}});
const DEMO_FACULTY=[{name:'Lydia Chilton',url:'https://www.engineering.columbia.edu/faculty-staff/directory/lydia-chilton',shared:['design','human-computer','creative'],excerpt:'Her Columbia profile describes work on AI and design, including creative problem-solving and applications in journalism and public libraries.',date:'2026-11-09',demoFocus:'AI-assisted design and creative problem-solving'},{name:'Brian A. Smith',url:'https://www.engineering.columbia.edu/faculty-staff/directory/brian-smith',shared:['accessibility','human-computer','technology'],excerpt:'His Columbia profile describes the Computer-Enabled Abilities Laboratory and work at the intersection of computing and human abilities.',date:'2026-11-09',demoFocus:'computing that expands human abilities and accessible experiences'}];
function demoSelectView(v){let b=document.querySelector('nav button[data-view="'+v+'"]');if(b)b.click()}
function loadDemoMatches(){state.results=DEMO_FACULTY;render();$('discoverySources').innerHTML='<a href="https://www.cs.columbia.edu/people/faculty/" target="_blank" rel="noopener">Computer Science directory ↗</a><span> · Demo uses two saved faculty examples.</span>';$('results').scrollIntoView({behavior:'smooth'});$('error').textContent='Demo: two source-backed examples. A real search reads live directory and faculty pages.'}
function startDemo(){if(!demoMode)demoBackup=structuredClone(state);demoMode=true;demoStep=0;$('error').textContent='';$('discoverySources').textContent='';state={cv:'Alex Sample — fictional demo applicant. Computer Science sophomore. Built a Python prototype for an accessible study planner; tested its interface with classmates. Coursework in data structures and statistics. Interested in human-computer interaction, design, accessibility, and educational technology.',applicant:'Alex Sample',major:'Computer Science',level:'Sophomore',interests:'Human-computer interaction, design, accessibility, educational technology',results:[],saved:[],apps:[],connections:[],plan:{major:'Computer Science',level:'Sophomore'}};syncProfile();$('demoBanner').classList.remove('hidden');demoSelectView('discover');render();$('demoHint').textContent='1 of 4 · Meet Alex, a fictional sophomore. Your saved profile is unchanged. Click Next to find faculty automatically.';$('demoNext').textContent='Find faculty →';window.scrollTo({top:0,behavior:'smooth'})}
function syncProfile(){['cv','major','level','applicant','interests','school','graduation','courses','skills','hours','payPreference'].forEach(k=>$(k).value=state[k]||'');words()}
$('startDemo').onclick=startDemo;$('demoNext').onclick=()=>{demoStep=(demoStep+1)%4;if(demoStep===1){demoSelectView('discover');loadDemoMatches();$('demoHint').textContent='2 of 4 · Two real faculty examples, selected without entering a URL. Try Draft outreach for a source-specific sample.';$('demoNext').textContent='Meet people →'}else if(demoStep===2){demoSelectView('opportunities');$('demoHint').textContent='3 of 4 · Named professionals and program contacts, plus industry pathways tailored to Alex’s major and level.';$('demoNext').textContent='Plan a coffee chat →'}else if(demoStep===3){demoSelectView('network');let p=rankedPeople()[0];openCalendar('coffee',p.name,p.url);$('demoHint').textContent='4 of 4 · Pick an agreed date and time. Google Calendar lets you review and Save; no invitations are sent by this app.';$('demoNext').textContent='Restart tour ↻'}else{startDemo()}window.scrollTo({top:0,behavior:'smooth'})};$('exitDemo').onclick=()=>{demoMode=false;state=demoBackup||state;demoBackup=null;syncProfile();$('demoBanner').classList.add('hidden');$('calendarDialog').close();$('draftDialog').close();$('error').textContent='';$('discoverySources').textContent='';render();demoSelectView('discover');toast('Your saved workspace is restored')};
function openDemoDraft(person){$('draftEvidence').classList.remove('hidden');$('draftEvidence').innerHTML='<b>Demo source snapshot</b><p>'+esc(person.excerpt)+'</p><a href="'+esc(person.url)+'" target="_blank" rel="noopener">Read real faculty profile ↗</a>';$('draft').value='Subject: Undergraduate research inquiry — '+person.demoFocus+'\n\nDear Professor '+person.name.split(' ').slice(-1)[0]+',\n\nI’m Alex Sample, a Computer Science sophomore exploring human-computer interaction. Your Columbia profile’s discussion of '+person.demoFocus+' caught my attention.\n\nI built a Python prototype for an accessible study planner and tested the interface with classmates. That project made me curious about how people use and evaluate interactive tools.\n\nAre you considering undergraduate students for projects in this area? I would appreciate learning which skills to develop and how to apply.\n\nThank you,\nAlex Sample\n\nDemo only — fictional applicant. Source: '+person.url;$('draftDialog').showModal()}
const SKILL_TERMS=['Python','SQL','JavaScript','TypeScript','Java','C++','R','Excel','Figma','React','HTML','CSS','MATLAB','Stata','SAS','Tableau','Power BI','Git','Linux','statistics','machine learning','data analysis','data entry','communication','writing','interviews','surveys','literature review','project management','cell culture','microscopy','PCR','bioinformatics','graphic design','prototyping','Google Apps'];
function phraseFound(text,phrase){let escaped=phrase.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return new RegExp('(^|[^a-z0-9])'+escaped+'(?=$|[^a-z0-9])','i').test(text||'')}
function profileText(p){return [p.cv,p.skills,p.courses,p.major,p.interests].filter(Boolean).join('\n')}
function localDay(){let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function evaluateOpportunity(item,profile){let why=[],gaps=[],conflicts=[],text=profileText(profile),desc=item.description||'',required=(item.requirements||[]).join(' ');let matched=SKILL_TERMS.filter(t=>phraseFound(desc,t)&&phraseFound(text,t));let unshown=SKILL_TERMS.filter(t=>phraseFound(required,t)&&!phraseFound(text,t));let overlap=(item.shared||[]).filter(t=>phraseFound(text,t));if(matched.length)why.push('Your CV / skills / courses mention '+matched.slice(0,5).join(', ')+', which also appear in the source.');if(overlap.length)why.push('Shared research terms: '+overlap.slice(0,4).join(', ')+'.');let majorWords=(profile.major||'').toLowerCase().match(/[a-z]{4,}/g)||[];let majorOverlap=majorWords.filter(t=>phraseFound(desc,t));if(majorOverlap.length)why.push('The source also mentions '+majorOverlap.join(', ')+', overlapping with your major.');if(!why.length)why.push('No clear skill overlap found in your profile. Review this as an exploratory option.');if(unshown.length)gaps.push('Not found in your CV / skills / courses: '+unshown.slice(0,5).join(', ')+'. This is a profile evidence gap, not proof you lack these skills.');
if(item.levels?.length&&profile.level&&!item.levels.includes(profile.level))conflicts.push('Source class / degree requirement does not match your '+profile.level+' level.');else if(item.levels?.length&&!profile.level)gaps.push('Add your class level to compare the source’s degree requirement.');
if(item.schools?.length&&profile.school&&!item.schools.includes(profile.school))conflicts.push('Source school restriction: '+item.schools.join(', ')+'. Your profile lists '+profile.school+'.');else if(item.schools?.length&&!profile.school)gaps.push('School eligibility must be checked: '+item.schools.join(', ')+'.');
if(item.weeklyHours&&Number(profile.hours)>0){if(Number(profile.hours)<item.weeklyHours)conflicts.push('Source lists '+item.weeklyHours+' hours/week; your profile allows '+profile.hours+'.');else why.push('Your weekly availability meets the listed '+item.weeklyHours+' hours.');}
if(item.graduationWindow&&profile.graduation){let y=Number(profile.graduation.slice(0,4));if(y<item.graduationWindow[0]||y>item.graduationWindow[1])conflicts.push('Source graduation-year window is '+item.graduationWindow.join('–')+'; your profile lists '+y+'.');}
if(profile.payPreference==='Paid only'&&item.payStatus!=='Paid')conflicts.push(item.payStatus==='Unpaid'?'This source describes an unpaid opportunity.':'Paid compensation is not confirmed by the source.');
let closed=item.status==='Closed'||(item.deadline&&item.deadline<localDay())||(item.expires&&item.expires.slice(0,10)<localDay());if(closed)conflicts.push('The source’s deadline or listing-expiry date has passed, or the source states it is closed.');if(!item.requirements?.length)gaps.push(item.type==='Faculty'?'Lab prerequisites and an available position are unverified.':'Full prerequisites were not extracted; check the original posting.');if(!item.levels?.length)gaps.push('Class-year / degree eligibility is not fully determined.');if(!item.deadline&&item.type!=='Faculty')gaps.push('No application deadline was found.');if(!profile.graduation)gaps.push('Add your graduation date to help review internship or graduate-role timing.');if(item.type!=='Faculty'&&!item.weeklyHours&&Number(profile.hours)>0)gaps.push('Weekly time commitment was not extracted; confirm that it fits your availability.');if(!gaps.length)gaps.push('Confirm all remaining prerequisites on the original source; this comparison covers only the extracted criteria.');
let cvEvidence=(profile.cv||'').split(/\n|(?<=[.!?])\s+/).filter(line=>line.length>20&&line.length<500).map(line=>({line,score:matched.filter(t=>phraseFound(line,t)).length+overlap.filter(t=>phraseFound(line,t)).length})).sort((a,b)=>b.score-a.score)[0];let next=closed?'Check the source for the next intake; do not apply using an expired deadline.':conflicts.length?'Resolve the listed eligibility or availability conflict before spending time on an application.':item.type==='Faculty'?'Read the faculty source, confirm student openings and prerequisites, then prepare a specific outreach email.':unshown.length?'Confirm the required skills and show a relevant project or course in your CV before applying.':'Review the full eligibility and application instructions on the source, then prepare the requested materials.';return {why,gaps,conflicts,closed,matched,cvEvidence:cvEvidence?.score>0?cvEvidence.line:'',score:matched.length*4+overlap.length*2+majorOverlap.length*3-conflicts.length*30,next,status:closed?'Closed':conflicts.length?'Profile conflict':'Review eligibility'}}

const EXTENDED_PROFILE=['school','graduation','courses','skills','hours','payPreference'];
EXTENDED_PROFILE.forEach(k=>{$(k).value=state[k]||'';$(k).onchange=()=>{state[k]=$(k).value;persist()}});
function matchExplanation(item){let a=evaluateOpportunity(item,state);return '<div class="match-review"><h3>Why it fits</h3><p>'+a.why.map(esc).join(' ')+'</p>'+(a.cvEvidence?'<div class="evidence"><b>CV evidence</b><br>“'+esc(a.cvEvidence)+'”</div>':'')+'<h3>What to check</h3><ul>'+[...a.conflicts,...a.gaps].map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><h3>Next step</h3><p>'+esc(a.next)+'</p></div>'}
function facultyReview(r){return '<details class="fit-details"><summary>Why this match · evidence & next step</summary>'+matchExplanation({title:r.name,description:r.excerpt,shared:r.shared,type:'Faculty',requirements:[]})+'</details>'}
function dateLabel(raw){if(!raw)return 'Not stated';let d=new Date(raw.length===10?raw+'T12:00:00':raw);return Number.isFinite(d.getTime())?d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):raw}
function liveItemCard(item){let a=evaluateOpportunity(item,state),saved=state.savedOpportunities?.some(x=>x.id===item.id);return '<article class="match live-card"><div class="row"><span class="eyebrow">'+esc(item.type)+' · '+esc(item.organization)+'</span><span class="tag '+(a.conflicts.length?'conflict':'')+'">'+esc(a.status)+'</span></div><h2 style="margin-top:13px">'+esc(item.title)+'</h2><p class="tiny">'+esc(item.location||'Location not stated')+' · '+esc(item.status)+'</p><div class="listing-meta"><div><b>Application deadline</b><span>'+esc(dateLabel(item.deadline))+'</span></div><div><b>Compensation</b><span>'+esc(item.payText||'Not stated')+'</span></div><div><b>Time commitment</b><span>'+esc(item.weeklyHours?item.weeklyHours+' hours / week':'Not stated')+'</span></div><div><b>Last checked</b><span>'+esc(dateLabel(item.checkedAt))+(demoMode?' · demo snapshot':'')+'</span></div></div>'+(item.expires?'<p class="tiny">Listing expiry (not an application deadline): '+esc(dateLabel(item.expires))+'</p>':'')+'<p>'+esc((item.summary||item.description||'').slice(0,420))+'…</p><details class="fit-details"><summary>Why it fits · gaps · next step</summary>'+matchExplanation(item)+'<h3>Source eligibility / qualifications</h3>'+(item.requirements?.length?'<ul>'+item.requirements.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'<p>Not extracted — review the source.</p>')+'</details><div class="person-actions"><a href="'+esc(item.url)+'" target="_blank" rel="noopener">Read posting & apply ↗</a><button class="secondary" data-save-op="'+esc(item.id)+'">'+(saved?'★ Saved':'☆ Save opportunity')+'</button><button class="primary" data-track-op="'+esc(item.id)+'">Track application</button><button class="secondary" data-calendar-op="'+esc(item.id)+'">▦ Plan deadline / task</button></div></article>'}
function renderLive(){let sourceList=state.liveSources||[];$('liveSources').innerHTML=sourceList.length?'<details class="source"><summary>Source coverage & check results</summary><ul>'+sourceList.map(s=>'<li><a target="_blank" rel="noopener" href="'+esc(s.url)+'">'+esc(s.name)+'</a> — '+esc(s.status)+(s.status==='Read'?' ('+s.count+' listings)':'')+'</li>').join('')+'</ul><p class="tiny">Public feeds only. This does not search private LionSHARE or UROP accounts, and it is not an exhaustive list of employers.</p></details>':'';let items=state.liveItems||[],showClosed=$('showClosed').checked,hideConflicts=$('hideConflicts').checked,type=$('liveType').value;let filtered=items.filter(i=>{let a=evaluateOpportunity(i,state);return (showClosed||!a.closed)&&(!hideConflicts||!a.conflicts.length)&&(!type||i.type===type)});let sort=$('liveSort').value;filtered.sort((a,b)=>sort==='deadline'?(a.deadline||'9999').localeCompare(b.deadline||'9999'):evaluateOpportunity(b,state).score-evaluateOpportunity(a,state).score);$('liveCount').textContent=items.length?filtered.length+' shown · '+(items.length-filtered.length)+' hidden by your filters'+(demoMode?' · Demo snapshots':''):'';$('liveResults').innerHTML=filtered.length?filtered.map(liveItemCard).join(''):items.length?'<div class="empty"><h2>No listings match these filters.</h2><p>Try showing profile conflicts, including closed listings, or changing your paid-work preference. Unknown pay is hidden when Paid only is selected and profile conflicts are hidden.</p></div>':'<div class="empty"><h2>A fresh place to start.</h2><p>Refresh public listings to read current employer and Columbia opportunity pages. Your profile shapes the explanations and filters.</p></div>';$('liveSummary').innerHTML='<div class="source"><b>'+(demoMode?'Demo opportunity snapshots':items.length?items.length+' public listings in your workspace':'Looking for actual openings?')+'</b><p class="tiny" style="margin:8px 0">'+(state.liveCheckedAt?'Last fetch: '+esc(dateLabel(state.liveCheckedAt))+'. ':'')+'See source-backed opportunities, deadlines where stated, and profile eligibility checks.</p><button class="secondary" id="openLive">Browse live opportunities →</button></div>';$('openLive').onclick=()=>demoSelectView('live')}
let liveLoading=false;async function refreshLive(){if(liveLoading)return;if(demoMode){state.liveItems=structuredClone(DEMO_OPPORTUNITIES);state.liveSources=[];render();toast('Demo uses saved source snapshots; no live search was run.');return}liveLoading=true;$('refreshLive').disabled=true;$('refreshLive').textContent='Reading public sources…';$('liveError').textContent='';try{let r=await fetch('/api/opportunities',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({major:state.major,cv:state.cv,skills:state.skills,courses:state.courses,level:state.level,school:state.school,hours:state.hours,graduation:state.graduation,payPreference:state.payPreference,interests:state.interests})});let d=await r.json();if(!r.ok)throw Error(d.error);if(!d.items.length&&d.sources.every(s=>s.status==='Unavailable'))throw Error('Public sources could not be read right now. Your previous listings are retained; try again later.');state.liveItems=d.items;state.liveSources=d.sources;state.liveCheckedAt=d.checkedAt;persist();$('liveError').textContent=d.sources.some(s=>s.status==='Unavailable')?'Some sources could not be read. Expand Source coverage to see which listings are missing.':''}catch(e){$('liveError').textContent=e.message}finally{liveLoading=false;$('refreshLive').disabled=false;$('refreshLive').textContent='↻ Refresh public listings'}}
$('refreshLive').onclick=refreshLive;['liveType','showClosed','hideConflicts','liveSort'].forEach(k=>$(k).onchange=renderLive);
function addApplication(record){let old=state.apps.find(a=>a.url===record.url);if(old){toast('Already in your application tracker');return old}let a={id:'app-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),status:'Drafting',date:new Date().toLocaleDateString(),draft:'',lastContacted:'',response:'',nextAction:'',followUp:'',...record};state.apps.push(a);persist();toast('Added to application tracker');return a}
function dueLabel(a){if(!a.followUp||a.status==='Closed')return '';return a.followUp<localDay()?'Follow-up overdue':a.followUp===localDay()?'Follow-up due today':'Follow-up '+dateLabel(a.followUp)}
function renderApplications(){let openTasks=state.apps.filter(a=>a.followUp&&a.followUp<=localDay()&&a.status!=='Closed');$('applications').innerHTML='<div class="panel" style="margin:15px 0"><div class="row"><div><h2>Your next actions</h2><p class="tiny" style="margin-bottom:0">'+openTasks.length+' follow-ups due or overdue. Tracking stays in this browser; schedule a calendar event for a reminder outside the app.</p></div><button class="secondary" id="newOutreach">＋ Add outreach</button></div></div>'+(state.apps.length?state.apps.map((a,i)=>'<article class="match"><div class="row"><div><span class="eyebrow">'+esc(a.kind||'Research outreach')+'</span><h2 style="margin-top:8px">'+esc(a.name)+'</h2></div><button class="secondary" data-remove="'+i+'">Remove</button></div><p class="tiny">Added '+esc(a.date)+'</p>'+(a.followUp?'<div class="due '+(a.followUp<=localDay()?'urgent':'')+'">'+esc(dueLabel(a))+'</div>':'')+'<div class="profile-grid"><div><label>Status</label><select data-app-field="status" data-app-index="'+i+'">'+['Drafting','Applied','Contacted','Replied','Follow-up','Interview','Offer','Closed'].map(s=>'<option '+(s===a.status?'selected':'')+'>'+s+'</option>').join('')+'</select></div><div><label>Last contacted</label><input type="date" data-app-field="lastContacted" data-app-index="'+i+'" value="'+esc(a.lastContacted)+'"></div><div><label>Next follow-up date</label><input type="date" data-app-field="followUp" data-app-index="'+i+'" value="'+esc(a.followUp)+'"></div><div><label>Next action</label><input data-app-field="nextAction" data-app-index="'+i+'" value="'+esc(a.nextAction)+'" placeholder="e.g. Ask about the interview timeline"></div></div><label>Response / conversation notes</label><textarea style="min-height:85px" data-app-field="response" data-app-index="'+i+'" placeholder="What did they say?">'+esc(a.response)+'</textarea><details style="margin:18px 0"><summary>Outreach draft / application notes</summary><textarea data-app-field="draft" data-app-index="'+i+'">'+esc(a.draft)+'</textarea></details><div class="person-actions">'+(a.url?'<a href="'+esc(a.url)+'" target="_blank" rel="noopener">Source / contact profile ↗</a>':'')+'<button class="secondary" data-followup="'+i+'">▦ Schedule follow-up reminder</button>'+calendarButton('coffee',a.name,a.url||'')+'</div></article>').join(''):'<div class="empty"><h2>Keep your next conversation moving.</h2><p>Track a live opportunity, log a networking contact, or add outreach manually.</p></div>');$('newOutreach').onclick=()=>{$('outreachForm').reset();$('outreachDialog').showModal()}}
document.addEventListener('change',e=>{let index=e.target.dataset.appIndex,field=e.target.dataset.appField;if(index!==undefined&&field){state.apps[Number(index)][field]=e.target.value;persist()}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let id=b.dataset.saveOp||b.dataset.trackOp||b.dataset.calendarOp;if(id){let item=[...(state.liveItems||[]),...(state.savedOpportunities||[])].find(o=>o.id===id);if(!item)return;if(b.dataset.saveOp){state.savedOpportunities=state.savedOpportunities||[];state.savedOpportunities=state.savedOpportunities.some(o=>o.id===id)?state.savedOpportunities.filter(o=>o.id!==id):[...state.savedOpportunities,item];persist()}if(b.dataset.trackOp){let a=evaluateOpportunity(item,state);addApplication({name:item.title+' — '+item.organization,url:item.url,kind:item.type,nextAction:a.next,followUp:'',opportunityId:item.id,draft:'Source: '+item.url+'\n\nApplication deadline: '+dateLabel(item.deadline)+'\n\n'+a.why.join('\n')})}if(b.dataset.calendarOp){openCalendar('deadline',item.title,item.url);if(item.deadline){$('eventDate').value=item.deadline;$('eventEndDate').value=item.deadline}}}if(b.dataset.logPerson){let p=rankedPeople().find(p=>p.id===b.dataset.logPerson);if(p)addApplication({name:p.name,url:p.url,kind:'Networking / coffee chat',draft:personOpener(p),nextAction:'Review the profile, then personalize an introductory message.'})}if(b.dataset.followup!==undefined){let a=state.apps[Number(b.dataset.followup)];openCalendar('followup',a.name,a.url||'');$('eventNotes').value=[a.nextAction,a.url?'Source: '+a.url:''].filter(Boolean).join('\n');if(a.followUp){$('eventDate').value=a.followUp;$('eventEndDate').value=a.followUp}}});
$('closeOutreach').onclick=()=>$('outreachDialog').close();$('outreachForm').onsubmit=e=>{e.preventDefault();let name=$('outreachName').value.trim(),url=$('outreachURL').value.trim();if(url){try{let u=new URL(url);if(u.protocol!=='https:')throw Error()}catch{$('outreachError').textContent='Use an HTTPS contact or opportunity URL, or leave it blank.';return}}addApplication({name,url,kind:$('outreachKind').value,nextAction:$('outreachNext').value});$('outreachDialog').close()};
$('file').onchange=async e=>{let file=e.target.files?.[0];if(!file)return;$('fileError').textContent='';let previous=$('filename').textContent;try{if(file.size>10*1024*1024)throw Error('Please choose a CV under 10 MB.');$('filename').textContent='Reading '+file.name+'…';let text;if(/\.pdf$/i.test(file.name)||file.type==='application/pdf'){let pdf=await import('/assets/pdf.mjs');pdf.GlobalWorkerOptions.workerSrc='/assets/pdf.worker.mjs';let task=pdf.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true});let doc;try{doc=await task.promise;if(doc.numPages>50)throw Error('This PDF has more than 50 pages. Upload a shorter CV.');let pages=[];for(let n=1;n<=doc.numPages;n++){let page=await doc.getPage(n),content=await page.getTextContent();pages.push(content.items.filter(i=>'str' in i).map(i=>i.str+(i.hasEOL?'\n':' ')).join(''))}text=pages.join('\n\n')}finally{await task.destroy()}if(text.trim().length<30)throw Error('This PDF has no readable text. Use a text-based PDF or paste text from an OCR version. Scanned PDFs are not supported.')}else if(/\.(txt|md)$/i.test(file.name)){text=await file.text()}else throw Error('Choose a PDF, TXT, or Markdown CV.');if(text.length>80000)throw Error('Extracted text is too long. Use a shorter CV or paste the relevant sections.');state.cv=text;$('cv').value=text;$('filename').textContent=file.name;words();persist();toast('CV text extracted. Review it before searching.')}catch(err){$('filename').textContent=previous;$('fileError').textContent=err.name==='PasswordException'?'This PDF is password protected. Upload an unlocked copy or paste its text.':err.message||'This PDF could not be read. Try another copy or paste its text.'}finally{e.target.value=''}};
