$('demoNext').onclick=()=>{demoStep=(demoStep+1)%6;if(demoStep===1){demoSelectView('discover');loadDemoMatches();$('demoHint').textContent='2 of 6 · Faculty examples show CV evidence, what to check, and a professor-specific email.';$('demoNext').textContent='Explore opportunities →'}else if(demoStep===2){demoSelectView('live');$('demoHint').textContent='3 of 6 · Source snapshots show compensation, stated deadlines, eligibility checks, and a next step. Real mode fetches current public sources.';$('demoNext').textContent='Meet people →'}else if(demoStep===3){demoSelectView('network');$('demoHint').textContent='4 of 6 · Named contacts have personalized openers. Log outreach to track the conversation.';$('demoNext').textContent='Track follow-ups →'}else if(demoStep===4){demoSelectView('applications');$('demoHint').textContent='5 of 6 · The fictional contact has a follow-up due today. Record a response or schedule a calendar reminder.';$('demoNext').textContent='Plan a coffee chat →'}else if(demoStep===5){demoSelectView('network');let p=rankedPeople()[0];openCalendar('coffee',p.name,p.url);$('demoHint').textContent='6 of 6 · Choose an agreed date and review the event in Google Calendar. The app sends no invitations.';$('demoNext').textContent='Restart tour ↻'}else startDemo();window.scrollTo({top:0,behavior:'smooth'})};

